export const onlyOfficeHandleCallback = <ThrowOnError extends boolean = false>(options: Options<OnlyOfficeHandleCallbackData, ThrowOnError>) => (options.client ?? client).post<OnlyOfficeHandleCallbackResponses, unknown, ThrowOnError>({
    url: '/api/onlyoffice/callback',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

